import i18n from '@dhis2/d2-i18n'
import React from 'react'
import { Link } from 'react-router-dom'
import { FetchError } from '@dhis2/app-runtime'
import {
    Button,
    ButtonStrip,
    CircularLoader,
    IconChevronLeft16,
    IconChevronRight16,
} from '@dhis2/ui'
import { useUserContext } from '../../../context'
import { Warning } from '@/components'
import { RefetchReports } from '../useReports'
import { ReportCard } from './reportCard'
import { NoMatches } from './noMatches'
import styles from './reportsList.module.css'
import { Pager } from '@/types/query'
import { ReportItem } from '@/types/report'

export const ReportsList = ({
    reports,
    loading,
    error,
    searchTerm,
    pager,
    refetchReports,
}: {
    reports: ReportItem[]
    loading: boolean
    error?: FetchError
    searchTerm: undefined | string
    pager: Pager
    refetchReports: RefetchReports
}) => {
    const { canAdd, canDelete } = useUserContext()
    return (
        <section className={styles.group}>
            <div className={styles.groupHeader}>
                <span className={styles.groupTitle}>
                    {i18n.t('Standard reports')}
                </span>
                {(canAdd || canDelete) && (
                    <Link
                        to="/standardReports/manage"
                        className={styles.groupAction}
                    >
                        <Button small>{i18n.t('Manage')}</Button>
                    </Link>
                )}
            </div>
            <div className={styles.grid}>
                {loading && <CircularLoader small />}
                {error && (
                    <Warning
                        error={true}
                        title={i18n.t('Reports information is not accessible')}
                    >
                        <span>
                            {i18n.t(
                                'There was a problem retrieving reports. Refresh the page to try again.'
                            )}
                        </span>
                    </Warning>
                )}
                {!loading && !error && (
                    <>
                        {reports.length === 0 ? (
                            <NoMatches searchTerm={searchTerm} />
                        ) : (
                            reports.map((report, index) => (
                                <ReportCard
                                    key={index}
                                    title={report.displayName}
                                    id={report?.id}
                                    linkDestination={report?.linkDestination}
                                />
                            ))
                        )}
                    </>
                )}
            </div>
            {pager.pageCount > 1 && (
                <div className={styles.navigationButtonsContainer}>
                    <ButtonStrip>
                        <Button
                            className={styles.buttonPrevious}
                            small
                            disabled={pager.page === 1}
                            onClick={() =>
                                refetchReports({
                                    searchTerm,
                                    page: pager.page - 1,
                                })
                            }
                        >
                            <div className={styles.navigatorIcon}>
                                <IconChevronLeft16 />
                            </div>
                            {i18n.t('Previous')}
                        </Button>

                        <Button
                            className={styles.buttonNext}
                            small
                            disabled={pager.page === pager.pageCount}
                            onClick={() =>
                                refetchReports({
                                    searchTerm,
                                    page: pager.page + 1,
                                })
                            }
                        >
                            {i18n.t('Next')}
                            <div className={styles.navigatorIcon}>
                                <IconChevronRight16 />
                            </div>
                        </Button>
                    </ButtonStrip>
                </div>
            )}
        </section>
    )
}
