import { useDataMutation } from '@dhis2/app-runtime'
import React from 'react'
import { ErrorReport } from '@/types/query'

type MutationError = ReturnType<typeof useDataMutation>[1]['error']

/* The validation messages the API attaches to a failed import, if any */
export const ErrorReportList = ({ error }: { error?: MutationError }) => {
    const errorReports = error?.details?.response?.errorReports as
        | ErrorReport[]
        | undefined

    if (!errorReports?.length) {
        return null
    }

    return (
        <ul>
            {errorReports.map(({ message }) => (
                <li key={message}>{message}</li>
            ))}
        </ul>
    )
}
