import i18n from '@dhis2/d2-i18n'
import { useConfig } from '@dhis2/app-runtime'
import React, { useCallback, useEffect, useState } from 'react'
import { useFixedPeriods } from './useFixedPeriods'
import { usePeriodField } from '../usePeriodField'
import {
    InputField,
    SingleSelectFieldFF,
    SingleSelectField,
    SingleSelectOption,
} from '@dhis2/ui'
import {
    createFixedPeriodFromPeriodId,
    getNowInCalendar,
} from '@dhis2/multi-calendar-dates'
import styles from './CustomFixedPeriodSelector.module.css'

// not exported by @dhis2/multi-calendar-dates, so derived structurally from
// a function that uses it (same approach as useFixedPeriods.ts)
type SupportedCalendar = Parameters<
    typeof createFixedPeriodFromPeriodId
>[0]['calendar']

type PeriodTypeOption = { value: string; label: string }

export const CustomFixedPeriodSelector = ({
    periodTypes,
    periodTypesLoading,
}: {
    periodTypes: PeriodTypeOption[]
    periodTypesLoading: boolean
}) => {
    // `calendar` is present on the real DHIS2 systemInfo response but
    // missing from this version of @dhis2/app-service-config's SystemInfo
    // type (same gap worked around in useFixedPeriods.ts)
    const calendar: string =
        (useConfig().systemInfo as { calendar?: string } | undefined)
            ?.calendar ?? 'gregory'

    const { periodInput, periodMeta, modifiedInput, setPeriod } =
        usePeriodField()

    const [{ year, periodType }, setYearAndPeriodType] = useState<{
        year: number
        periodType: string
    }>(() => {
        if (periodInput.value) {
            const fixedPeriod = createFixedPeriodFromPeriodId({
                periodId: periodInput.value,
                calendar: calendar as SupportedCalendar,
            })
            // startDate is a 'YYYY-MM-DD' string already in the given
            // calendar (not converted to/from gregorian), so its year can
            // be read directly.
            return {
                year: parseInt(fixedPeriod.startDate.split('-')[0], 10),
                periodType: fixedPeriod.periodType,
            }
        }
        const now = getNowInCalendar(calendar)
        return {
            year: now.eraYear ?? now.year,
            periodType: periodTypes[0]?.value ?? '',
        }
    })
    const periods = useFixedPeriods({ periodType, year })

    // when there's only one generated period for the current period type
    // and year, select it automatically instead of leaving the field empty
    useEffect(() => {
        if (periods.length === 1 && periods[0].value) {
            const onlyOption = periods[0].value
            if (periodInput.value !== onlyOption) {
                setPeriod(onlyOption)
                periodInput.onChange(onlyOption)
            }
        }
    }, [periods, periodInput.value, periodInput.onChange, setPeriod])

    const changeYears = useCallback(
        (year: number) => {
            periodInput.onChange(undefined)
            setPeriod(undefined)
            setYearAndPeriodType((current) => ({ ...current, year }))
        },
        [periodInput.onChange, setYearAndPeriodType, setPeriod]
    )

    const changePeriodType = useCallback(
        (periodType: string) => {
            periodInput.onChange(undefined)
            setPeriod(undefined)
            setYearAndPeriodType((current) => ({ ...current, periodType }))
        },
        [periodInput.onChange, setYearAndPeriodType, setPeriod]
    )

    return (
        <>
            <SingleSelectField
                className={styles.fullWidthField}
                loading={periodTypesLoading}
                selected={periodType}
                onChange={({ selected }) => {
                    changePeriodType(selected)
                }}
                label={i18n.t('Period type')}
                required={true}
            >
                {periodTypes.map((periodType: PeriodTypeOption) => (
                    <SingleSelectOption
                        key={periodType.value}
                        label={periodType.label}
                        value={periodType.value}
                    />
                ))}
            </SingleSelectField>
            <div className={styles.subFields}>
                <InputField
                    type="number"
                    className={styles.fullWidthField}
                    label={i18n.t('Year')}
                    value={String(year)}
                    onChange={(s: { value?: string; name?: string }) =>
                        changeYears(Number(s.value))
                    }
                />
                <SingleSelectFieldFF
                    className={styles.fullWidthField}
                    name="period"
                    dataTest="standardReport-periodTypeSelector"
                    label={i18n.t('Reporting period')}
                    options={periods ?? []}
                    input={modifiedInput}
                    meta={periodMeta}
                    required
                    disabled={periods.length === 1}
                />
            </div>
        </>
    )
}
