import { useDataQuery } from '@dhis2/app-runtime'
import i18n from '@dhis2/d2-i18n'
import { CircularLoader, NoticeBox } from '@dhis2/ui'
import React from 'react'
import { useParams } from 'react-router-dom'
import { FormColumn, FormPage } from '../form/FormPage'
import { StoredReport } from '../form/reportFormValues'
import { StandardReportForm } from '../form/StandardReportForm'
import { DynamicResourceQuery } from '@/types/query'
import { ReportAccess } from '@/types/report'

// `:owner` holds what a full PUT sends back (incl. sharing and the design),
// except relativePeriods, which has to be asked for separately
const REPORT_QUERY: { report: DynamicResourceQuery } = {
    report: {
        resource: 'reports',
        id: ({ id }) => id,
        params: { fields: [':owner', 'relativePeriods', 'access'] },
    },
}

type ReportQueryResponse = {
    report: StoredReport & { access: ReportAccess }
}

const EditContent = ({ reportId }: { reportId?: string }) => {
    const { loading, error, data } = useDataQuery<ReportQueryResponse>(
        REPORT_QUERY,
        { variables: { id: reportId } }
    )

    if (loading) {
        return (
            <FormColumn>
                <CircularLoader small />
            </FormColumn>
        )
    }
    if (error || !data) {
        return (
            <FormColumn>
                <NoticeBox
                    error
                    title={i18n.t('Error loading requested report')}
                >
                    {error?.message}
                </NoticeBox>
            </FormColumn>
        )
    }
    if (!data.report.access.update) {
        return (
            <FormColumn>
                <NoticeBox warning>
                    {i18n.t('You do not have access to edit this report')}
                </NoticeBox>
            </FormColumn>
        )
    }

    return <StandardReportForm existingReport={data.report} />
}

export const StandardReportEdit = () => {
    const { reportId } = useParams()

    return (
        <FormPage title={i18n.t('Edit standard report')}>
            <EditContent reportId={reportId} />
        </FormPage>
    )
}
