import { useDataQuery } from '@dhis2/app-runtime'
import i18n from '@dhis2/d2-i18n'
import { CircularLoader } from '@dhis2/ui'
import React from 'react'
import { Warning } from '../../components/index'
import { UserContext, User } from './user-context'

const query = {
    me: {
        resource: 'me',
        params: {
            paging: false,
            fields: [
                'id',
                'authorities',
                'organisationUnits',
                'dataViewOrgansiationUnits',
            ],
        },
    },
    userSettings: {
        resource: 'userSettings',
    },
}

type UserQueryResponse = {
    me: User
    userSettings: { keyUiLocale: string }
}

const ADD_AUTHORITIES = ['F_REPORT_PUBLIC_ADD', 'F_REPORT_PRIVATE_ADD', 'ALL']
const DELETE_AUTHORITIES = ['F_REPORT_DELETE', 'ALL']

const UserProvider = ({ children }: { children: React.ReactNode }) => {
    const {
        data,
        loading,
        error,
        refetch: refetchUser,
    } = useDataQuery<UserQueryResponse>(query)

    if (loading) {
        return <CircularLoader />
    }

    if (error) {
        /**
         * user error boundary
         */
        return (
            <Warning
                error={true}
                title={i18n.t('User information is not accessible')}
            >
                <span>
                    {i18n.t(
                        'There was a problem retrieving user information. Refresh the page to try again.'
                    )}
                </span>
            </Warning>
        )
    }

    const { authorities } = data?.me ?? { me: {} }
    const { organisationUnits, dataViewOrganisationUnits } = data?.me ?? {
        me: {},
    }
    const userSettings = data?.userSettings

    const providerValue = {
        canAdd:
            authorities?.some((auth) => ADD_AUTHORITIES.includes(auth)) ??
            false,
        canDelete:
            authorities?.some((auth) => DELETE_AUTHORITIES.includes(auth)) ??
            false,
        organisationUnits: (
            (dataViewOrganisationUnits?.length
                ? dataViewOrganisationUnits
                : organisationUnits) ?? []
        ).map(({ id }) => id),
        keyUiLocale: userSettings?.keyUiLocale ?? 'en',
        refetchUser,
    }
    console.log('providerValue user', providerValue)

    return (
        <UserContext.Provider value={providerValue}>
            {children}
        </UserContext.Provider>
    )
}

export { UserProvider }
