import { useDataQuery } from '@dhis2/app-runtime'
import { DynamicResourceQuery, Pager } from '@/types/query'
import { Report } from '@/types/report'

const BASE_PARAMS = {
    fields: ['id', 'displayName', 'lastUpdated', 'access'],
    order: 'displayName:iasc',
    pageSize: 50,
    filters: ['type:eq:HTML'],
}

const query: { reports: DynamicResourceQuery } = {
    reports: {
        resource: 'reports',
        params: ({
            searchTerm,
            page = 1,
            pageSize = BASE_PARAMS.pageSize,
            order = BASE_PARAMS.order,
        }: {
            searchTerm?: string
            page?: number
            pageSize?: number
            order?: string
        }) => {
            const params = { ...BASE_PARAMS, order, page, pageSize }
            if (searchTerm) {
                params.filters = ['type:eq:HTML', `name:ilike:${searchTerm}`]
            }
            return params
        },
    },
}

type ReportsQueryResponse = {
    reports: {
        reports: Report[]
        pager: Pager
    }
}

export type RefetchReports = ReturnType<
    typeof useDataQuery<ReportsQueryResponse>
>['refetch']

// p
const DEFAULT_PAGER: Pager = {
    page: 1,
    total: 0,
    pageSize: BASE_PARAMS.pageSize,
    pageCount: 1,
}

export const useReports = () => {
    const {
        data,
        loading,
        error,
        refetch: refetchReports,
    } = useDataQuery<ReportsQueryResponse>(query)

    const reportsObject = data?.reports?.reports ?? []

    return {
        reports: reportsObject,
        pager:
            reportsObject.length === 0
                ? DEFAULT_PAGER
                : data?.reports?.pager ?? DEFAULT_PAGER,
        refetchReports,
        loading,
        error,
    }
}
