import i18n from '@dhis2/d2-i18n'
import { useConfig, useDataQuery } from '@dhis2/app-runtime'
import { CircularLoader, NoticeBox } from '@dhis2/ui'
import React, { useContext, useState } from 'react'
import { useParams } from 'react-router-dom'
import { Form } from 'react-final-form'
import { ReportDefaultLayout } from '../../../components'
import { DynamicResourceQuery } from '@/types/query'
import { ParametersSelector } from './parametersSelector/ParametersSelector'
import { ReportInfoQueryResponse, queryFields } from './types'
import {
    getStandardReportsContextSnapshot,
    useUserContext,
} from '../../../context'

const REPORT_INFO_QUERY: { report: DynamicResourceQuery } = {
    report: {
        resource: 'reports',
        id: ({ id }) => id,
        params: {
            paging: false,
            fields: queryFields,
        },
    },
}

export const StandardReportView = () => {
    const { reportId } = useParams()
    // `calendar` is present on the real DHIS2 systemInfo response but
    // missing from this version of @dhis2/app-service-config's SystemInfo
    // type (same gap worked around in useFixedPeriods.ts)
    const calendar: string =
        (useConfig().systemInfo as { calendar?: string } | undefined)
            ?.calendar ?? 'gregory'

    // Read once on mount; kept in state to avoid recalculation
    const [initialValues] = useState(
        getStandardReportsContextSnapshot(calendar)
    )
    const { loading, error, data } = useDataQuery<ReportInfoQueryResponse>(
        REPORT_INFO_QUERY,
        { variables: { id: reportId } }
    )
    const { canAdd, canDelete } = useUserContext()
    if (loading) {
        return <CircularLoader />
    }
    const { report } = data ?? { report: undefined }
    if (error || !reportId || !report) {
        return (
            <NoticeBox error title={i18n.t('Error loading requested report')} />
        )
    }

    return (
        <Form
            initialValues={initialValues}
            onSubmit={() => {
                console.log('execute reports query')
            }}
            render={({ handleSubmit }) => (
                <ReportDefaultLayout
                    currentLocationString={report.displayName}
                    ParametersSelector={<ParametersSelector report={report} />}
                    ReportContent={
                        <div>{`report content for id: ${reportId}`}</div>
                    }
                    isEmpty={true}
                    onSubmit={handleSubmit}
                    additionalPath={
                        canAdd || canDelete
                            ? {
                                  location: '/standardReports/manage',
                                  text: i18n.t('Manage'),
                              }
                            : undefined
                    }
                />
            )}
        ></Form>
    )
}
